193	  BLOCK_PAD_TOP: 20, BLOCK_PAD_BOTTOM: 16, BLOCK_GAP: 26,
194	  BTN_ROW_H: 30, RADIO_GAP: 36, TOOLBAR_H: 30, MAX_W: 1400,
195	};
