245	  const sepX = inputX + S.BOX_W + S.SEP_GAP;
246	  const highX = sepX + 10;
247	  const rangeDropX = highX + S.BOX_W + 2;
248	  const rangeNoteX = rangeDropX + 28;
249	
250	  // A labelled choice group (leading COMMENT on a BEGIN OF LINE) starts its options right after
251	  // the widest group label — like SAP's short COMMENT column — aligned across all labelled groups.
252	  const groupLabels = [];
