254	    if (isChoiceGroup(selItemType(it)) && it.label) groupLabels.push(approxTextWidthPx(it.label));
255	  }
256	  const groupOptX = S.LABEL_X + (groupLabels.length ? Math.max(...groupLabels) : 0) + 40;
257	  const groupX = (it) => (it.label ? groupOptX : S.LABEL_X);
258	  // Width: base grid + note reserve, widened for toolbar / horizontal choice groups, capped.
259	  const radioW = (o) => 20 + approxTextWidthPx(selLabelText(o));
260	  let need = rangeNoteX + 200;
261	  if (toolbar.length) need = Math.max(need, 20 + toolbar.reduce((s, t) => s + approxTextWidthPx(toolbarText(t)) + 34, 0));
262	  for (const b of blocks) for (const it of b.items) {
263	    const t = selItemType(it);
264	    const noteW = it.note ? approxTextWidthPx(it.note) + 20 : 0;
265	    if (isChoiceGroup(t)) {
266	      const opts = it.options || [];
267	      const optsW = it.layout === 'horizontal'
268	        ? opts.reduce((s, o) => s + radioW(o) + S.RADIO_GAP, 0)
