277	        : 0;
278	      need = Math.max(need, noteX + noteW);
279	    }
280	  }
281	  const w = Math.min(S.MAX_W, Math.max(900, need));
282	
283	  let y = toolbar.length ? S.TOOLBAR_H + 12 : 0;
284	  const placed = [];
285	  for (const b of blocks) {
286	    const top = y + 20;
287	    let cy = top + S.BLOCK_PAD_TOP;
288	    const rows = [];
289	    for (const it of b.items) {
290	      const t = selItemType(it);
291	      if (isChoiceGroup(t)) {
292	        const opts = it.options || [];
293	        const lines = [];
294	        const x0 = groupX(it);
