299	            if (line.length && x + ow > w - 30) { lines.push(line); line = []; x = x0; }
300	            line.push({ o, x });
301	            x += ow + S.RADIO_GAP;
302	          }
303	          if (line.length) lines.push(line);
304	        } else {
305	          for (const o of opts) lines.push([{ o, x: x0 }]);
