344	  const note = (x, n) => (n ? `<text x="${x}" y="{B}" fill="#666">${xmlT(n)}</text>` : '');
345	  const at = (s, base) => s.replace(/\{Y\}/g, String(base - 12)).replace(/\{B\}/g, String(base));
346	
347	  // Toolbar (application toolbar buttons on the selection screen).
348	  let tbSvg = '';
349	  if (lay.toolbar.length) {
350	    let x = 14;
351	    const parts = [`<rect x="0" y="0" width="${w}" height="${S.TOOLBAR_H}" fill="#EEF3F8" stroke="#C9D6E3"/>`];
352	    for (const t of lay.toolbar) {
353	      const label = toolbarText(t);
354	      const bw = approxTextWidthPx(label) + 24;
355	      parts.push(`<rect x="${x}" y="5" width="${bw}" height="20" rx="3" fill="#FFFFFF" stroke="#9AA7B4"/><text x="${x + bw / 2}" y="19" text-anchor="middle">${xml(label)}</text>`);
