357	    }
358	    tbSvg = parts.join('');
359	  }
360	
361	  const blockSvg = lay.blocks.map(b => {
362	    const frame = `<rect x="10" y="${b.top}" width="${w - 20}" height="${b.h}" rx="8" fill="#FFFFFF" stroke="#3E7DB3" stroke-width="1.3" filter="url(#imgsh)"/>`
363	      + (b.label
364	        ? `<rect x="28" y="${b.top - 9}" width="${Math.max(70, approxTextWidthPx(b.label) + 46)}" height="18" rx="4" fill="#DCE7F1" stroke="#9DBBD6"/>`
