371	        const label = `<text x="${S.LABEL_X}" y="${base}">${xml(selLabelText(it))}</text>`;
372	        // NO-EXTENSION removes the multiple-selection button.
373	        if (it.noIntervals) {
374	          const dx = inputX + S.BOX_W + 2;
375	          return star + label + at(box(inputX, it.default)
