404	          const lb = y + li * S.rowH + S.rowH - 6;
405	          return line.map(({ o, x }) => {
406	            const text = selLabelText(o);
407	            lastBase = lb; lastEnd = x + 20 + approxTextWidthPx(text);
408	            const mark = radio
409	              ? `<circle cx="${x + 6}" cy="${lb - 4}" r="6" fill="#FFF" stroke="#555"/>`
410	                + (opts.indexOf(o) === selIdx ? `<circle cx="${x + 6}" cy="${lb - 4}" r="3" fill="#333"/>` : '')
