412	                + (o.checked ? `<path d="M${x + 2},${lb - 4} l3,3 l6,-7" fill="none" stroke="#1F4E79" stroke-width="1.6"/>` : '');
413	            return mark + `<text x="${x + 18}" y="${lb}">${xml(text)}</text>`;
414	          }).join('');
415	        }).join('');
416	        return head + svg + at(note(lastEnd + 20, it.note), lastBase);
417	      }
418	      if (t === 'pushbutton') {
419	        const text = String(it.label ?? '');
420	        const bw = Math.max(120, approxTextWidthPx(text) + 40);
421	        const by = y + 4;
422	        return `<rect x="${S.LABEL_X}" y="${by}" width="${bw}" height="20" rx="3" fill="#FCE9A0" stroke="#C9A646"/>`
423	          + `<text x="${S.LABEL_X + bw / 2}" y="${by + 14}" text-anchor="middle">${xml(text)}</text>`
424	          + (it.note ? `<text x="${S.LABEL_X + bw + 14}" y="${by + 14}" fill="#666">${xml(it.note)}</text>` : '');
425	      }
426	      if (t === 'comment') {
427	        return `<text x="${S.LABEL_X}" y="${base}" fill="#444">${xml(it.text ?? it.label ?? '')}</text>`;
