429	      // 'param' (PARAMETERS) — no multiple-selection button on a real screen.
430	      const label = `<text x="${S.LABEL_X}" y="${base}">${xml(selLabelText(it))}</text>`;
431	      return star + label + at(box(inputX, it.default) + note(inputX + S.BOX_W + 14, it.note), base);
432	    }).join('');
433	    return frame + rows;
434	  }).join('\n');
