436	  // Dynamic legend — only items that apply to this spec.
437	  const all = lay.blocks.flatMap(b => b.rows.map(r => r));
438	  const ranges = all.filter(r => r.t === 'range');
439	  const legendParts = [];
440	  if (all.some(r => r.it.required)) legendParts.push(`<tspan fill="#B00020" font-weight="700">*</tspan> ${xml(L.required)}`);
