442	  if (ranges.some(r => !r.it.noIntervals)) legendParts.push(xml(L.range));
443	  const legendSvg = legendParts.length
444	    ? `<text x="25" y="${legendY}" fill="#555" font-size="11">${legendParts.join(' · ')}</text>`
