457	/**
458	 * Schema lint for image-spec.selection — returns human-readable warnings.
459	 * The legacy shape cannot express pushbuttons, radio groups or more than two
460	 * blocks, so writers silently flattened them (radios drawn as checkboxes).
461	 */
462	export function selectionSchemaWarnings(selection) {
463	  if (!selection) return [];
464	  const warns = [];
465	  const hasBlocks = Array.isArray(selection.blocks) && selection.blocks.length > 0;
466	  if (!hasBlocks && (selection.fields?.length || selection.optionFields?.length)) {
467	    warns.push('selection uses the legacy fields/optionFields shape — pushbuttons, radio groups and multiple blocks cannot be drawn. Use selection.blocks[] (skills/program-to-spec/selection-schema.md).');
468	    const radios = (selection.optionFields || []).filter(f => !f.type && /^R_/i.test(f.name || '')).map(f => f.name);
469	    if (radios.length) warns.push(`optionFields ${radios.join(', ')} look like RADIOBUTTONs but render as checkboxes — use a { type: "radioGroup" } item.`);
470	  }
471	  const known = new Set(['param', 'range', 'checkbox', 'checkboxGroup', 'radioGroup', 'pushbutton', 'comment']);
472	  for (const b of (selection.blocks || [])) for (const it of (b?.items || [])) {
473	    if (it?.type && !known.has(it.type)) warns.push(`unknown selection item type "${it.type}" (${it.name || it.label || '?'}) — rendered as a plain parameter.`);
474	    if (isChoiceGroup(it?.type) && !(it.options || []).length) warns.push(`${it.type} ${it.group || it.label || '?'} has no options.`);
475	  }
476	  return warns;
477	}
