2387	    ? (Array.isArray(buttonFlows) ? buttonFlows : [])
2388	      .map((f, i) => ({ ...f, number: i + 1 }))
2389	      .filter(f => isRenderableFlow(f) && flowIndex.get(flowKey(f.source, f.code)) === f.number)
2390	    : [];
2391	  // PARALLEL RENDERING — selection + ALV + processFlow rasterize concurrently.
2392	  // Each rasterizeSvgToPng() spawns its own headless browser process, so
2393	  // Promise.all() cuts wall-clock time roughly in half. Each task is
2394	  // self-contained: a rasterize failure or timeout in one does not affect
2395	  // the other — the output of the failed branch simply stays null and the
2396	  // caller falls back to the cell-border wireframe for that section only.
2397	  const tasks = [];
2398	  if (selection) {
2399	    tasks.push((async () => {
2400	      try {
