2402	        // Use the shared metrics helper so we stay in lockstep with the
2403	        // renderer's actual layout — avoids the bug where a longer label
2404	        // widened the SVG but the viewport stayed at 900 and cropped it.
2405	        const { width, height } = selectionScreenMetrics(selection);
