2423	    // panes that have a toolbar — a writer's natural reading of the flag.
2424	    if (isMultipane && spec.standardToolbar) {
2425	      spec = { ...spec, panes: spec.panes.map(p => (p?.toolbar?.length && p.standardToolbar === undefined ? { ...p, standardToolbar: true } : p)) };
