2435	    tasks.push((async () => {
2436	      try { out.alv = await renderOutputScreen(alv); } catch { /* keep alv null → wireframe fallback */ }
2437	    })());
2438	  }
2439	  // v15: further screens a button opens (popups 0200/0300…, detail dynpros).
2440	  const extraScreens = renderScreens && Array.isArray(screens) ? screens.filter(s => s && typeof s === 'object') : [];
2441	  const screenResults = new Array(extraScreens.length).fill(null);
2442	  extraScreens.forEach((s, i) => {
2443	    tasks.push((async () => {
2444	      try {
2445	        const r = await renderOutputScreen(s);
2446	        if (r) screenResults[i] = { dynnr: String(s.dynnr || `S${i + 1}`), title: s.screen?.title || '', ...r };
2447	      } catch { /* this screen stays out; its Markdown table stands alone */ }
2448	    })());
2449	  });
