2451	  //   · string[]          → legacy linear horizontal flow (back-compat)
2452	  //   · { nodes, edges }  → v12 branching flowchart (Mermaid-style TD), the
2453	  //                         richer form that mirrors the Markdown spec's flow
2454	  //                         with decisions / exception side-paths / loop-backs.
2455	  const isGraph = processFlow && !Array.isArray(processFlow) && Array.isArray(processFlow.nodes);
