    menuPath: 'Menu Path', objType: '区分', cbo: 'CBO', standard: '標準', transaction: 'Transaction',
    description: 'Description', intro: '概要', purpose: '業務目的', background: '業務背景',
    rules: 'Business Rule', users: '利用者', flow: '処理フロー', scenarios: '業務シナリオ',
