553	const ALV_LEGEND_PAD = 44;
554	const ALV_PLAIN_PAD = 16;
555	
556	export function renderAlvLayoutSVG({ columns = [], sampleRows = [], maxRows = 3, lang = 'ko' } = {}) {
557	  const L = legendFor(lang);
558	  const rows = sampleRows.slice(0, Math.max(1, Math.min(maxRows, 5)));
559	  const totalW = columns.reduce((s, c) => s + alvColW(c), 0) + 20;
560	  const w = Math.max(900, Math.min(totalW, 1600));
561	  const rowH = 24;
562	  const headerH = 22;
563	  // Spec-driven legend feature detection — only include items that apply.
564	  const hasStatus   = columns.some(c => c.name === '_status') || rows.some(r => r && r._status);
565	  const hasHotspot  = columns.some(c => c.hotspot);
566	  const hasEditable = columns.some(c => c.editable);
567	  const hasLegend   = hasStatus || hasHotspot || hasEditable;
568	  // The legend's baseline sits 30 px under the grid; 44 leaves room for its
569	  // descenders. (It was 80, which left a band of empty space under every grid.)
570	  const legendPad   = hasLegend ? ALV_LEGEND_PAD : ALV_PLAIN_PAD;
571	  const h = 10 + headerH + rows.length * rowH + legendPad;
