node -e '
const fs=require("fs");const p=".sc4sap/work/HKT-DEV/manuals/_draft/ZSDR24730-ko.manual.json";
const m=JSON.parse(fs.readFileSync(p,"utf8"));const S=m.screens;
const T0100="[AP] Inquiry Order List(3 Records)";
const ico={REFR:"ICON_REFRESH",CONV:"ICON_TRANSPORT",CRT_DO:"ICON_DELIVERY",SIMU:"ICON_SIMULATE",CRT_DOSHP:"ICON_DELIVERY",CRT_BILL:"ICON_PAYMENT"};
const fixBtns=bs=>bs.forEach(b=>{if(ico[b.code])b.icon=ico[b.code];});
fixBtns(S["0100"].screen.buttons);S["0100"].screen.status="S0100";
S["0100"].toolbar=["|",{code:"SETGRP",label:"Set Group",icon:"ICON_OPERATOR"}];
const fixFields=fs_=>fs_&&fs_.forEach(f=>{if(f.code==="APPLY")f.icon="ICON_OKAY";});
fixFields(S["0100"].screen.fields);
// Dialog statuses: only the application-toolbar buttons (BUT) are drawn; icon-only when ICON_TEXT is empty.
S["0200"].screen={...S["0200"].screen,title:T0100,status:"S0200",buttons:[{code:"DETACH",label:"Detach All Error Occured Group",icon:"ICON_DISCONNECT"},"|",{code:"OKAY",icon:"ICON_OKAY",flow:false}]};
S["0300"].screen={...S["0300"].screen,title:T0100,status:"S0300",buttons:[{code:"EXIT",icon:"ICON_CANCEL",flow:false}]};
S["0400"].screen={...S["0400"].screen,title:T0100,status:"S0400",buttons:[{code:"EXIT",icon:"ICON_CANCEL",flow:false},{code:"CREATE",label:"Create DN",icon:"ICON_OKAY"}]};
// POPUP_TO_CONFIRM defaults: blank title, Yes / No / Cancel.
const conf=b=>b.map(x=>x);const CB=[{code:"YES",label:"Yes"},{code:"NO",label:"No",flow:false},{code:"CANCEL",label:"Cancel",icon:"ICON_CANCEL",flow:false}];
S.confirm.screen={...S.confirm.screen,title:"",buttons:CB};
let n=0;
m.scenarios.forEach(sc=>sc.steps.forEach(st=>{
  if(st.patch?.screen?.buttons){ if(st.screen==="confirm"){st.patch.screen.title="";st.patch.screen.buttons=CB;n++;} else {fixBtns(st.patch.screen.buttons);fixFields(st.patch.screen.fields);st.patch.screen.status=st.patch.screen.status||"S0100";} }
  if(st.screen==="confirm")(st.callouts||[]).forEach(c=>{ if(c.anchor==="pai:NO")c.text="**No** 또는 **Cancel**을 누르면 아무것도 처리하지 않고 닫힙니다."; if(c.anchor==="title")c.anchor="fld:"+ (st.patch?.screen?.fields?.[0]?.name||"") ; });
  (st.callouts||[]).forEach(c=>{ if(st.screen==="0200"&&c.anchor==="pai:EXIT")c._drop=true; });
  if(st.callouts)st.callouts=st.callouts.filter(c=>!c._drop);
}));
fs.writeFileSync(p,JSON.stringify(m,null,2)+"\n");console.log("confirm steps",n);'; node -e '
