// Sample pixel colours from an 8-bit PNG: node png-sample.mjs <file> x,y [x,y ...]
import { readFileSync } from 'node:fs';
import { inflateSync } from 'node:zlib';

const [file, ...pts] = process.argv.slice(2);
const buf = readFileSync(file);
let i = 8, ihdr, idat = [], plte;
while (i < buf.length) {
  const len = buf.readUInt32BE(i), type = buf.toString('ascii', i + 4, i + 8), data = buf.subarray(i + 8, i + 8 + len);
  if (type === 'IHDR') ihdr = data; else if (type === 'IDAT') idat.push(data); else if (type === 'PLTE') plte = data;
  i += 12 + len;
}
const w = ihdr.readUInt32BE(0), h = ihdr.readUInt32BE(4), depth = ihdr[8], ct = ihdr[9];
if (depth !== 8) throw new Error('8-bit only');
const bpp = { 0: 1, 2: 3, 3: 1, 4: 2, 6: 4 }[ct];
const raw = inflateSync(Buffer.concat(idat));
const stride = w * bpp, out = Buffer.alloc(h * stride);
for (let y = 0; y < h; y++) {
  const f = raw[y * (stride + 1)], src = raw.subarray(y * (stride + 1) + 1, (y + 1) * (stride + 1));
  for (let x = 0; x < stride; x++) {
    const a = x >= bpp ? out[y * stride + x - bpp] : 0, b = y ? out[(y - 1) * stride + x] : 0;
    const c = x >= bpp && y ? out[(y - 1) * stride + x - bpp] : 0;
    let v = src[x];
    if (f === 1) v += a; else if (f === 2) v += b; else if (f === 3) v += (a + b) >> 1;
    else if (f === 4) { const p = a + b - c, pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c); v += pa <= pb && pa <= pc ? a : pb <= pc ? b : c; }
    out[y * stride + x] = v & 255;
  }
}
const hex = (r, g, b) => '#' + [r, g, b].map(n => n.toString(16).padStart(2, '0')).join('').toUpperCase();
console.log(`${file.split(/[\\/]/).pop()} ${w}x${h}`);
for (const p of pts) {
  const [label, xy] = p.includes('=') ? p.split('=') : [p, p];
  const [x, y] = xy.split(',').map(Number);
  const o = y * stride + x * bpp;
  const rgb = ct === 3 ? [plte[out[o] * 3], plte[out[o] * 3 + 1], plte[out[o] * 3 + 2]] : ct === 0 ? [out[o], out[o], out[o]] : [out[o], out[o + 1], out[o + 2]];
  console.log(`  ${label.padEnd(14)} (${x},${y}) ${hex(...rgb)}`);
}

