360	export function renderSelectionScreenSVG({ lang = 'ko', ...selection } = {}) {
361	  const lay = layoutSelectionScreen(selection, lang);
362	  const { L, w, h, inputX, sepX, highX, rangeDropX, rangeNoteX, legendY } = lay;
363	  const S = SEL;
364	  // User text inside at() templates escapes '{' so it can never collide with the {Y}/{B} placeholders.
365	  const xmlT = (s) => xml(s).replace(/\{/g, '&#123;');
366	  // Long defaults are truncated with '…' so they never spill out of the box into the note.
367	  const fit = (v) => {
368	    let out = '';
369	    for (const ch of String(v)) {
370	      if (approxTextWidthPx(out + ch + '…') > S.BOX_W - 8) return out + '…';
371	      out += ch;
372	    }
373	    return out;
374	  };
375	  const box = (x, val) => `<rect x="${x}" y="{Y}" width="${S.BOX_W}" height="16" fill="#FFFFFF" stroke="#9AA7B4" rx="2"/>`
376	    + (val != null && val !== '' ? `<text x="${x + 4}" y="{B}" fill="#555">${xmlT(fit(val))}</text>` : '');
377	  const drop = (x) => `<rect x="${x}" y="{Y}" width="16" height="16" fill="#E7EEF5" stroke="#9AA7B4" rx="2"/><text x="${x + 8}" y="{B}" text-anchor="middle">▼</text>`;
378	  const note = (x, n) => (n ? `<text x="${x}" y="{B}" fill="#666">${xmlT(n)}</text>` : '');
379	  const at = (s, base) => s.replace(/\{Y\}/g, String(base - 12)).replace(/\{B\}/g, String(base));
380	
381	  // Toolbar (application toolbar buttons on the selection screen).
382	  let tbSvg = '';
383	  if (lay.toolbar.length) {
384	    let x = 14;
385	    const parts = [`<rect x="0" y="0" width="${w}" height="${S.TOOLBAR_H}" fill="#EEF3F8" stroke="#C9D6E3"/>`];
386	    for (const t of lay.toolbar) {
387	      const label = toolbarText(t);
388	      const bw = approxTextWidthPx(label) + 24;
389	      parts.push(anchored(anchorKey('tb', t?.code || label),
390	        `<rect x="${x}" y="5" width="${bw}" height="20" rx="3" fill="#FFFFFF" stroke="#9AA7B4"/><text x="${x + bw / 2}" y="19" text-anchor="middle">${xml(label)}</text>`));
391	      x += bw + 10;
392	    }
393	    tbSvg = parts.join('');
394	  }
395	
396	  const rowSvg = ({ it, t, y, lines, h: frameH }) => {
397	    if (t === 'frame') {
398	      const fw = w - 2 * S.FRAME_X;
399	      const label = it.label
400	        ? `<rect x="${S.FRAME_X + 10}" y="${y - 3}" width="${approxTextWidthPx(it.label) + 14}" height="14" fill="#FFFFFF"/>`
401	          + `<text x="${S.FRAME_X + 17}" y="${y + 8}" font-size="11.5" font-weight="700" fill="#24598F">${xml(it.label)}</text>`
402	        : '';
403	      return `<rect x="${S.FRAME_X}" y="${y + 4}" width="${fw}" height="${frameH - 4}" rx="5" fill="none" stroke="#9DBBD6"/>${label}`;
404	    }
405	    const base = y + S.rowH - 6;
406	    const star = it.required ? `<text x="25" y="${base}" fill="#B00020" font-weight="700">*</text>` : '';
407	    if (t === 'range') {
408	      const label = `<text x="${S.LABEL_X}" y="${base}">${xml(selLabelText(it))}</text>`;
409	      // NO-EXTENSION removes the multiple-selection button.
410	      if (it.noIntervals) {
411	        const dx = inputX + S.BOX_W + 2;
412	        return star + label + at(box(inputX, it.default)
413	          + (it.noExtension ? note(dx + 12, it.note) : drop(dx) + note(dx + 28, it.note)), base);
414	      }
415	      return star + label + at(
416	        box(inputX, it.default) + `<text x="${sepX}" y="{B}" text-anchor="middle">~</text>`
417	        + box(highX, it.defaultHigh) + (it.noExtension ? '' : drop(rangeDropX)) + note(rangeNoteX, it.note), base);
418	    }
419	    if (t === 'checkbox') {
420	      const text = selLabelText(it);
421	      // labelLeft: COMMENT … FOR FIELD before the checkbox → text in the label column, box at the input column.
422	      const bx = it.labelLeft ? inputX : S.LABEL_X;
423	      const mark = it.checked
424	        ? `<path d="M${bx + 2},${base - 4} l3,3 l6,-7" fill="none" stroke="#1F4E79" stroke-width="1.6"/>` : '';
425	      const box12 = `<rect x="${bx}" y="${base - 10}" width="12" height="12" fill="#FFF" stroke="#555"/>${mark}`;
426	      if (it.labelLeft) {
427	        return `<text x="${S.LABEL_X}" y="${base}">${xml(text)}</text>` + box12
428	          + at(note(inputX + 30, it.note), base);
429	      }
430	      return box12
431	        + `<text x="${S.LABEL_X + 20}" y="${base}">${xml(text)}</text>`
432	        + at(note(S.LABEL_X + 40 + approxTextWidthPx(text), it.note), base);
433	    }
434	    if (isChoiceGroup(t)) {
435	      const opts = it.options || [];
436	      const radio = t === 'radioGroup';
437	      const selIdx = Math.max(0, opts.findIndex(o => o?.selected));
438	      let lastBase = base, lastEnd = S.LABEL_X;
439	      const head = it.label ? `<text x="${S.LABEL_X}" y="${base}">${xml(it.label)}</text>` : '';
440	      const svg = (lines || []).map((line, li) => {
441	        const lb = y + li * S.rowH + S.rowH - 6;
442	        return line.map(({ o, x }) => {
443	          const text = selLabelText(o);
444	          lastBase = lb; lastEnd = x + 20 + approxTextWidthPx(text);
445	          const mark = radio
446	            ? `<circle cx="${x + 6}" cy="${lb - 4}" r="6" fill="#FFF" stroke="#555"/>`
447	              + (opts.indexOf(o) === selIdx ? `<circle cx="${x + 6}" cy="${lb - 4}" r="3" fill="#333"/>` : '')
448	            : `<rect x="${x}" y="${lb - 10}" width="12" height="12" fill="#FFF" stroke="#555"/>`
449	              + (o.checked ? `<path d="M${x + 2},${lb - 4} l3,3 l6,-7" fill="none" stroke="#1F4E79" stroke-width="1.6"/>` : '');
450	          return anchored(anchorKey('sel', o.name), mark + `<text x="${x + 18}" y="${lb}">${xml(text)}</text>`);
451	        }).join('');
452	      }).join('');
453	      return head + svg + at(note(lastEnd + 20, it.note), lastBase);
454	    }
455	    if (t === 'pushbutton') {
456	      const text = String(it.label ?? '');
457	      const bw = Math.max(120, approxTextWidthPx(text) + 40);
458	      const by = y + 4;
