670	export function renderAlvLayoutSVG({ columns = [], sampleRows = [], maxRows = 3, lang = 'ko' } = {}) {
671	  const L = legendFor(lang);
672	  const rows = sampleRows.slice(0, Math.max(1, Math.min(maxRows, 5)));
673	  const totalW = columns.reduce((s, c) => s + alvColW(c), 0) + 20;
674	  // No upper cap: a capped canvas cut off the columns past it without a word.
675	  const w = Math.max(900, totalW);
676	  const rowH = 24;
677	  const headerH = 22;
678	  // Spec-driven legend feature detection — only include items that apply.
679	  const hasStatus   = columns.some(c => c.name === '_status') || rows.some(r => r && r._status);
680	  const hasHotspot  = columns.some(c => c.hotspot);
681	  const hasEditable = columns.some(c => c.editable);
682	  const hasLegend   = hasStatus || hasHotspot || hasEditable;
683	  // The legend's baseline sits 30 px under the grid; 44 leaves room for its
684	  // descenders. (It was 80, which left a band of empty space under every grid.)
685	  const legendPad   = hasLegend ? ALV_LEGEND_PAD : ALV_PLAIN_PAD;
686	  const h = 10 + headerH + rows.length * rowH + legendPad;
687	
688	  let x = 10;
689	  const colX = columns.map(c => { const left = x; x += alvColW(c); return left; });
690	  const gridRight = x;
691	
692	  const headerCells = columns.map((c, i) => {
693	    const cx = colX[i] + alvColW(c) / 2;
694	    const text = `<text x="${cx}" y="${10 + headerH - 7}" text-anchor="middle" font-weight="700" fill="#FFFFFF">${xml(alvHeaderText(c))}</text>`;
695	    // The unfilled rect gives the anchor the whole header cell as its box.
696	    return anchored(anchorKey('col', c.name), `<rect x="${colX[i]}" y="10" width="${alvColW(c)}" height="${headerH}" fill="none"/>${text}`);
697	  }).join('');
698	
699	  const sepLines = colX.slice(1).map(lx =>
700	    `<line x1="${lx}" y1="${10 + headerH}" x2="${lx}" y2="${10 + headerH + rows.length * rowH}" stroke="#C8D4E2"/>`).join('');
701	
702	  const dataRows = rows.map((r, rIdx) => {
703	    const y = 10 + headerH + rIdx * rowH;
704	    const bg = r._locked ? '#F0F5FA' : (rIdx % 2 === 1 ? '#F5F9FC' : '#FFF');
